import ctypes

class GSLVector:
    def __init__(self, data):
        self.data = (ctypes.c_double * len(data))(*data)
        self.size = len(data)

def vector_add(a, b):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    vec_a = GSLVector(a)
    vec_b = GSLVector(b)

    if vec_a.size != vec_b.size:
        raise ValueError("Vectors must be of the same size")

    result = (ctypes.c_double * vec_a.size)()

    gsl.gsl_vector_add(result, vec_a.data, vec_b.data)

    return list(result)

import ctypes

def allocate_and_free_workspace(n):
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl.gsl_sum_levin_utrunc_alloc.restype = ctypes.c_void_p
        workspace_ptr = gsl.gsl_sum_levin_utrunc_alloc(n)

        if not workspace_ptr:
            return False

        gsl.gsl_sum_levin_utrunc_free(workspace_ptr)
        return True

    except Exception:
        return False

