class GSLMatrix:
    def __init__(self, data_ptr, size1, size2):
        self.data_ptr = data_ptr
        self.size1 = size1
        self.size2 = size2

def create_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if np_array.ndim != 2:
        raise ValueError("Array must be 2-dimensional")

    # Create GSL matrix structure (simplified representation)
    data_ptr = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return GSLMatrix(data_ptr, np_array.shape[0], np_array.shape[1])

def copy_matrix(dest, src):
    if not isinstance(dest, GSLMatrix) or not isinstance(src, GSLMatrix):
        raise ValueError("Both arguments must be GSLMatrix instances")
    if dest.size1 != src.size1 or dest.size2 != src.size2:
        raise ValueError("Matrices must have the same dimensions")

    # Define gsl_matrix_memcpy function signature
    gsl.gsl_matrix_memcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
    gsl.gsl_matrix_memcpy.restype = ctypes.c_int

    # Call the GSL function
    result = gsl.gsl_matrix_memcpy(dest.data_ptr, src.data_ptr)
    return result

