import sys

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except Exception as e:
        print(f"Error loading GSL libraries: {e}", file=sys.stderr)
        sys.exit(1)

def gsl_cdf_beta_Pinv(P, a, b):
    gsl = load_gsl_libraries()
    try:
        gsl.gsl_cdf_beta_Pinv.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
        gsl.gsl_cdf_beta_Pinv.restype = ctypes.c_double
        result = gsl.gsl_cdf_beta_Pinv(P, a, b)
        return result
    except Exception as e:
        print(f"Error computing inverse CDF: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    test_cases = [
        (0.5, 2.0, 2.0),
        (0.25, 1.0, 1.0),
        (0.75, 0.5, 0.5)
    ]
    for P, a, b in test_cases:
        try:
            result = gsl_cdf_beta_Pinv(P, a, b)
            print(f"P={P}, a={a}, b={b} -> {result}")
        except Exception as e:
            print(f"Test failed for P={P}, a={a}, b={b}: {e}", file=sys.stderr)

