import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.ptr = gsl_matrix_alloc(rows, cols)
        if not self.ptr:
            raise MemoryError("Failed to allocate GSL matrix")
        self.rows = rows
        self.cols = cols

    def __del__(self):
        if hasattr(self, 'ptr') and self.ptr:
            gsl_matrix_free(self.ptr)

def gsl_matrix_alloc(rows, cols):
    func = gsl.gsl_matrix_alloc
    func.argtypes = [ctypes.c_size_t, ctypes.c_size_t]
    func.restype = ctypes.c_void_p
    return func(rows, cols)

def gsl_matrix_free(matrix_ptr):
    func = gsl.gsl_matrix_free
    func.argtypes = [ctypes.c_void_p]
    func(matrix_ptr)

def numpy_to_gsl_matrix(np_array):
    if len(np_array.shape) != 2:
        raise ValueError("Input must be a 2D array")
    rows, cols = np_array.shape
    gsl_mat = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            set_gsl_matrix_element(gsl_mat.ptr, i, j, np_array[i, j])
    return gsl_mat

def set_gsl_matrix_element(matrix_ptr, i, j, value):
    func = gsl.gsl_matrix_set
    func.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_size_t, ctypes.c_double]
    func(matrix_ptr, i, j, value)

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl_matrix.rows
    cols = gsl_matrix.cols
    np_array = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            np_array[i, j] = get_gsl_matrix_element(gsl_matrix.ptr, i, j)
    return np_array

def get_gsl_matrix_element(matrix_ptr, i, j):
    func = gsl.gsl_matrix_get
    func.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_size_t]
    func.restype = ctypes.c_double
    return func(matrix_ptr, i, j)

