    jacobian_gsl = numpy_to_gsl_matrix(jacobian)
    n = jacobian.shape[1]
    covar_gsl = GSLMatrix(n, n)
    result = func(jacobian_gsl.ptr, epsrel, covar_gsl.ptr)
    if result != 0:
        raise RuntimeError(f"gsl_multifit_covar failed with error code {result}")
