class GslSfResult(ctypes.Structure):
    _fields_ = [("val", ctypes.c_double), ("err", ctypes.c_double)]

def compute_beta(x, y):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_sf_beta_e.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.POINTER(GslSfResult)]
        gsl.gsl_sf_beta_e.restype = ctypes.c_int
        result = GslSfResult()
        status = gsl.gsl_sf_beta_e(x, y, ctypes.byref(result))
        if status != 0:
            raise ValueError(f"GSL error: {status}")
        return result.val
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python beta.py <x> <y>", file=sys.stderr)
        sys.exit(1)
    try:
        x = float(sys.argv[1])
        y = float(sys.argv[2])
        if x <= 0 or y <= 0:
            raise ValueError("x and y must be positive")
        beta_val = compute_beta(x, y)
        print(beta_val)
