import ctypes
import sys

class GSLVector:
    def __init__(self, data):
        self.size = len(data)
        self.data = (ctypes.c_double * self.size)(*data)

def create_gsl_vector(data):
    return GSLVector(data)

def main():
    if len(sys.argv) < 3:
        print("Usage: python script.py <size> <data1> <data2> ...")
        return

    size = int(sys.argv[1])
    data = list(map(float, sys.argv[2:2+size]))

    cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_vector_memcpy.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
    gsl.gsl_vector_memcpy.restype = ctypes.c_int

    src_vector = create_gsl_vector(data)
    dest_vector = create_gsl_vector([0.0] * size)

    result = gsl.gsl_vector_memcpy(ctypes.byref(dest_vector.data), ctypes.byref(src_vector.data))

    if result == 0:
        dest_data = [dest_vector.data[i] for i in range(size)]
        print(dest_data)
    else:
        print("Copy failed")

if __name__ == "__main__":
    main()

