def compute_median_mad(data, scale):
    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    n = len(data)
    if n == 0:
        return (float('nan'), float('nan'))

    data_array = (ctypes.c_double * n)(*data)

    median = gsl.gsl_stats_median(data_array, 1, n)
    mad = gsl.gsl_stats_mad0(data_array, 1, n, median)

    scaled_mad = scale * mad

    return (median, scaled_mad)

