import os

def symmetric_rank2_update(order, uplo, N, alpha, X, incX, Y, incY, A, lda):
    try:
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer")
    if not isinstance(incX, int) or incX <= 0:
        raise ValueError("incX must be a positive integer")
    if not isinstance(incY, int) or incY <= 0:
        raise ValueError("incY must be a positive integer")
    if not isinstance(lda, int) or lda < N:
        raise ValueError("lda must be an integer >= N")
    if len(X) < 1 + (N - 1) * abs(incX):
        raise ValueError("X array too small for given N and incX")
    if len(Y) < 1 + (N - 1) * abs(incY):
        raise ValueError("Y array too small for given N and incY")
    if len(A) < lda * N:
        raise ValueError("A array too small for given lda and N")

    c_float_p = ctypes.POINTER(ctypes.c_float)

    X_arr = (ctypes.c_float * len(X))(*X)
    Y_arr = (ctypes.c_float * len(Y))(*Y)
    A_arr = (ctypes.c_float * len(A))(*A)

    libgslcblas.cblas_ssyr2(order, uplo, N, ctypes.c_float(alpha), 
                           X_arr, incX, Y_arr, incY, A_arr, lda)

    return list(A_arr)

import ctypes
import os

def symmetric_rank2_update(order, uplo, N, alpha, X, incX, Y, incY, A, lda):
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer")
    if not isinstance(incX, int) or incX <= 0:
        raise ValueError("incX must be a positive integer")
    if not isinstance(incY, int) or incY <= 0:
        raise ValueError("incY must be a positive integer")
    if not isinstance(lda, int) or lda < N:
        raise ValueError("lda must be an integer >= N")
    if len(X) < (N - 1) * abs(incX) + 1:
        raise ValueError("X vector too short for given N and incX")
    if len(Y) < (N - 1) * abs(incY) + 1:
        raise ValueError("Y vector too short for given N and incY")
    if len(A) < lda * N:
        raise ValueError("A matrix too small for given N and lda")

    c_float_p = ctypes.POINTER(ctypes.c_float)

    cblas.cblas_ssyr2.restype = None
    cblas.cblas_ssyr2.argtypes = [
        ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_float,
        c_float_p, ctypes.c_int, c_float_p, ctypes.c_int, c_float_p, ctypes.c_int
    ]

    X_arr = (ctypes.c_float * len(X))(*X)
    Y_arr = (ctypes.c_float * len(Y))(*Y)
    A_arr = (ctypes.c_float * len(A))(*A)

    cblas.cblas_ssyr2(
        order, uplo, N, alpha,
        X_arr, incX, Y_arr, incY, A_arr, lda
    )

    return list(A_arr)

