def allocate_rng(rng_name):
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    except OSError:
        print("Error: Failed to load libgslcblas.so")
        return None
    try:
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        print("Error: Failed to load libgsl.so")
        return None
    gsl.gsl_rng_alloc.restype = ctypes.c_void_p
    gsl.gsl_rng_alloc.argtypes = [ctypes.c_void_p]
    gsl.gsl_rng_env_setup.restype = None
    gsl.gsl_rng_env_setup()
    rng_type_ptr = gsl.gsl_rng_types_setup()
    if not rng_type_ptr:
        print("Error: Failed to get RNG types")
        return None
    rng_type = ctypes.cast(rng_type_ptr, ctypes.POINTER(ctypes.c_void_p))
    found = False
    i = 0
    while rng_type[i]:
        type_name = ctypes.cast(rng_type[i], ctypes.c_char_p).value.decode('utf-8')
        if type_name == rng_name:
            found = True
            break
        i += 1
    if not found:
        print(f"Error: RNG type '{rng_name}' not found")
        return None
    rng_ptr = gsl.gsl_rng_alloc(rng_type[i])
    if not rng_ptr:
        print("Error: Failed to allocate RNG")
        return None
    return ctypes.c_void_p(rng_ptr)

