import ctypes.util

class GSLFunction(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)), ("params", ctypes.c_void_p)]

def integrate(function, a, b, epsabs, epsrel):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_integration_qng.argtypes = [ctypes.POINTER(GSLFunction), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_size_t)]
    gsl.gsl_integration_qng.restype = ctypes.c_int

    def wrapper(x, params):
        return function(x)

    c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(wrapper)
    gsl_func = GSLFunction(c_func, None)

    result = ctypes.c_double()
    abserr = ctypes.c_double()
    neval = ctypes.c_size_t()

    status = gsl.gsl_integration_qng(ctypes.byref(gsl_func), a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(neval))

    if status != 0:
        raise RuntimeError(f"Integration failed with status {status}")

    return result.value, abserr.value, neval.value

