    cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl_integration_qng = gsl.gsl_integration_qng
    gsl_integration_qng.argtypes = [ctypes.POINTER(GSLFunction), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_size_t)]
    gsl_integration_qng.restype = ctypes.c_int

    result = ctypes.c_double()
    abserr = ctypes.c_double()
    neval = ctypes.c_size_t()

    func_type = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)
    def wrapper(x, params):
        return function(x)

    gsl_func = GSLFunction(func_type(wrapper), None)

    status = gsl_integration_qng(ctypes.byref(gsl_func), a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(neval))

