import sys

def compute_bessel_Y1(x):
    if not isinstance(x, (int, float)) or x <= 0:
        raise ValueError("Input must be a positive floating-point number")

    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    except OSError:
        raise RuntimeError("Failed to load libgslcblas.so")

    try:
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        raise RuntimeError("Failed to load libgsl.so")

    gsl.gsl_sf_bessel_Y1.argtypes = [ctypes.c_double]
    gsl.gsl_sf_bessel_Y1.restype = ctypes.c_double

    result = gsl.gsl_sf_bessel_Y1(x)
    return result

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <x>")
        sys.exit(1)

    try:
        x = float(sys.argv[1])
        result = compute_bessel_Y1(x)
        print(result)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
