    gsl = load_gsl_libraries()
    try:
        gsl.gsl_sf_bessel_J0.argtypes = [ctypes.c_double]
        gsl.gsl_sf_bessel_J0.restype = ctypes.c_double
        result = gsl.gsl_sf_bessel_J0(x)
        return result
    except AttributeError:
        print("Error: gsl_sf_bessel_J0 function not found in GSL library", file=sys.stderr)
        sys.exit(1)

