class GSLFunction(ctypes.Structure):
    _fields_ = [("function", ctypes.c_void_p), ("params", ctypes.c_void_p)]

class GSLIntegrationWorkspace(ctypes.Structure):
    pass

# Set up function prototypes
gsl.gsl_integration_qag.argtypes = [
    ctypes.POINTER(GSLFunction), ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_size_t, ctypes.c_int, ctypes.POINTER(GSLIntegrationWorkspace), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)
]
gsl.gsl_integration_qag.restype = ctypes.c_int

gsl.gsl_integration_workspace_alloc.argtypes = [ctypes.c_size_t]
gsl.gsl_integration_workspace_alloc.restype = ctypes.POINTER(GSLIntegrationWorkspace)

gsl.gsl_integration_workspace_free.argtypes = [ctypes.POINTER(GSLIntegrationWorkspace)]

gsl.gsl_integration_workspace_free.restype = None

# Callback function type
INTEGRAND_FUNC = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)

def integrate(function, a, b, epsabs, epsrel, limit, key):
    workspace = gsl.gsl_integration_workspace_alloc(limit)
    if not workspace:
        raise MemoryError("Failed to allocate integration workspace")

