        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    if not isinstance(k, int) or k <= 0:
        raise ValueError("k must be a positive integer")
    if not isinstance(array, list) or len(array) == 0:
        raise ValueError("array must be a non-empty list")
    if k > len(array):
        raise ValueError("k cannot be larger than the array length")

    n = len(array)
    c_array = (ctypes.c_double * n)(*array)
    p = (ctypes.c_size_t * k)()

