import ctypes

class GSLException(Exception):
    pass

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except Exception as e:
        raise GSLException(f"Failed to load GSL libraries: {e}")

def configure_gsl_stats_mean(gsl):
    try:
        gsl.gsl_stats_mean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
        gsl.gsl_stats_mean.restype = ctypes.c_double
    except Exception as e:
        raise GSLException(f"Failed to configure gsl_stats_mean: {e}")

def compute_mean(data, stride, size):
    try:
        gsl = load_gsl_libraries()
        configure_gsl_stats_mean(gsl)
        data_array = (ctypes.c_double * len(data))(*data)
        mean = gsl.gsl_stats_mean(data_array, stride, size)
        return mean
    except Exception as e:
