import ctypes
import sys

class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = data[i][j]

def create_gsl_matrix(matrix):
    return GSLMatrix(matrix)

def extract_matrix(gsl_matrix):
    result = []
    for i in range(gsl_matrix.rows):
        row = []
        for j in range(gsl_matrix.cols):
            row.append(gsl_matrix.data[i * gsl_matrix.cols + j])
        result.append(row)
    return result

def main():
    cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_matrix_alloc.restype = ctypes.c_void_p
    gsl.gsl_matrix_free.argtypes = [ctypes.c_void_p]

    apply_givens_qr = gsl.apply_givens_qr
    apply_givens_qr.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_double, ctypes.c_double]
    apply_givens_qr.restype = None

    Q_input = [[1.0, 0.0], [0.0, 1.0]]
    R_input = [[3.0, 4.0], [0.0, 5.0]]
    i, j, c, s = 0, 1, 0.6, 0.8

    Q_gsl = create_gsl_matrix(Q_input)
    R_gsl = create_gsl_matrix(R_input)

    M = Q_gsl.rows
    N = R_gsl.cols

    apply_givens_qr(M, N, ctypes.byref(Q_gsl.data), ctypes.byref(R_gsl.data), i, j, c, s)

    Q_output = extract_matrix(Q_gsl)
    R_output = extract_matrix(R_gsl)

    expected_Q = [[0.6, -0.8], [0.8, 0.6]]
    expected_R = [[5.0, 0.0], [0.0, 5.0]]

    for i_row in range(M):
        for j_col in range(M):
            assert abs(Q_output[i_row][j_col] - expected_Q[i_row][j_col]) < 1e-10

    for i_row in range(M):
        for j_col in range(N):
            assert abs(R_output[i_row][j_col] - expected_R[i_row][j_col]) < 1e-10

    return Q_output, R_output

if __name__ == "__main__":
    main()

