import ctypes
import sys

class GSLVector:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.vector = None

    def create_gsl_vector(self):
        try:
            libgsl.gsl_vector_alloc.restype = ctypes.c_void_p
            self.vector = libgsl.gsl_vector_alloc(self.size)
            if not self.vector:
                raise MemoryError("Failed to allocate GSL vector")

            for i in range(self.size):
                libgsl.gsl_vector_set(self.vector, i, self.data[i])
            return self.vector
        except Exception as e:
            print(f"Error creating GSL vector: {e}", file=sys.stderr)
            return None

    def free(self):
        if self.vector:
            libgsl.gsl_vector_free(self.vector)

def scaled_enorm(d, f):
    try:
        libgsl.gsl_blas_dscal.restype = None
        libgsl.gsl_blas_dscal(d, f.vector)

        libgsl.gsl_blas_dnrm2.restype = ctypes.c_double
        norm = libgsl.gsl_blas_dnrm2(f.vector)
        return norm
    except Exception as e:
        print(f"Error computing scaled Euclidean norm: {e}", file=sys.stderr)
        return float('nan')

