                    print(f"Test {i+1}: Empty vector input", file=sys.stderr)
                    continue

                vec1 = GSLVector(vec1_data)
                vec2 = GSLVector(vec2_data)

                if vec1.create_gsl_vector() is None or vec2.create_gsl_vector() is None:
                    print(f"Test {i+1}: Vector creation failed", file=sys.stderr)
                    continue

                result = scaled_enorm(scale, vec2)
                print(f"Test {i+1}: Scaled norm = {result}")

