import ctypes
import sys

class GSLVector:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.gsl_vector = None

    def __del__(self):
        if self.gsl_vector:
            gsl.gsl_vector_free(self.gsl_vector)

def create_gsl_vector(data):
    if not isinstance(data, list):
        raise TypeError("Input must be a list")
    if not all(isinstance(x, (int, float)) for x in data):
        raise ValueError("All elements must be numeric")
    vec = GSLVector(data)
    vec.gsl_vector = gsl.gsl_vector_alloc(vec.size)
    if not vec.gsl_vector:
        raise MemoryError("Failed to allocate GSL vector")
    for i, val in enumerate(data):
        gsl.gsl_vector_set(vec.gsl_vector, i, val)
    return vec

def scaled_enorm(d, f):
    if not isinstance(d, GSLVector) or not isinstance(f, GSLVector):
        raise TypeError("Both arguments must be GSLVector instances")
    if d.size != f.size:
        raise ValueError("Vectors must have the same size")
    func = gsl.gsl_blas_dnrm2
    func.argtypes = [ctypes.c_void_p]
    func.restype = ctypes.c_double
    norm_d = func(d.gsl_vector)
    norm_f = func(f.gsl_vector)
    if norm_f == 0.0:
        raise ZeroDivisionError("Second vector has zero norm")
    return norm_d / norm_f

