        vec2 = create_gsl_vector([1.0, 1.0])
        result1 = scaled_enorm(vec1, vec2)
        print(f"Test 1 result: {result1}")

        # Test 2: Zero vector in denominator
        try:
            vec3 = create_gsl_vector([0.0, 0.0])
            result2 = scaled_enorm(vec1, vec3)
        except ZeroDivisionError as e:
            print(f"Test 2 passed: {e}")

        # Test 3: Different sizes
        try:
            vec4 = create_gsl_vector([1.0])
            result3 = scaled_enorm(vec1, vec4)
        except ValueError as e:
