        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except Exception as e:
        print(f"Error loading GSL libraries: {e}")
        sys.exit(1)

def compute_gastwirth_mean(sorted_data, stride, n):
    if n == 0:
        return float('nan')
    if not isinstance(sorted_data, list) or not all(isinstance(x, float) for x in sorted_data):
        raise ValueError("sorted_data must be a list of floats")
    if not isinstance(stride, int) or stride <= 0:
        raise ValueError("stride must be a positive integer")
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if len(sorted_data) < n * stride:
        raise ValueError("sorted_data length is insufficient for given n and stride")

    gsl = load_gsl_libraries()
    gsl.gsl_stats_gastwirth_from_sorted_data.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
    gsl.gsl_stats_gastwirth_from_sorted_data.restype = ctypes.c_double

    data_array = (ctypes.c_double * len(sorted_data))(*sorted_data)
    result = gsl.gsl_stats_gastwirth_from_sorted_data(data_array, stride, n)
    return result

if __name__ == "__main__":
    import unittest

    class TestGastwirthMean(unittest.TestCase):
        def test_empty_list(self):
            self.assertTrue(ctypes.isnan(compute_gastwirth_mean([], 1, 0)))

        def test_single_element(self):
            self.assertEqual(compute_gastwirth_mean([1.0], 1, 1), 1.0)

        def test_three_elements(self):
            data = [1.0, 2.0, 3.0]
            result = compute_gastwirth_mean(data, 1, 3)
            self.assertAlmostEqual(result, 2.0, places=6)

        def test_stride_2(self):
            data = [1.0, 0.0, 2.0, 0.0, 3.0, 0.0]
            result = compute_gastwirth_mean(data, 2, 3)
            self.assertAlmostEqual(result, 2.0, places=6)

    unittest.main()

