    if len(data) < n * stride:
        raise ValueError("data array too small for given n and stride")

    # Convert lists to ctypes arrays
    w_array = (ctypes.c_double * len(w))(*w)
    data_array = (ctypes.c_double * len(data))(*data)

    # Call GSL function
