import ctypes
import numpy as np

# Load GSL libraries
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix:
    def __init__(self, data):
        n = len(data)
        self.size = n
        self.data = (ctypes.c_double * (n * n))()
        for i in range(n):
            for j in range(n):
                self.data[i * n + j] = data[i][j]

def matrix_to_gsl(matrix):
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Input matrix must be square")
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix):
    n = gsl_matrix.size
    result = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(gsl_matrix.data[i * n + j])
        result.append(row)
    return result

def compute_matrix_exponential(matrix, mode):
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise TypeError("Input must be a 2D list")
    n = len(matrix)
    if n == 0:
        raise ValueError("Matrix cannot be empty")
    for row in matrix:
        if len(row) != n:
            raise ValueError("Input matrix must be square")
    gsl_mat = matrix_to_gsl(matrix)
    result_mat = GSLMatrix([[0.0] * n for _ in range(n)])
    gsl.gsl_linalg_exponential_ss(ctypes.byref(gsl_mat), ctypes.byref(result_mat), ctypes.c_int(mode))
    return gsl_matrix_to_numpy(result_mat)

# Test cases
def test_matrix_exponential():
    # Test with identity matrix
    identity = [[1.0, 0.0], [0.0, 1.0]]
    result = compute_matrix_exponential(identity, 0)
    expected = [[np.exp(1.0), 0.0], [0.0, np.exp(1.0)]]
    assert np.allclose(result, expected), f"Identity test failed: {result} != {expected}"

    # Test with zero matrix
    zero = [[0.0, 0.0], [0.0, 0.0]]
    result = compute_matrix_exponential(zero, 0)
    expected = [[1.0, 0.0], [0.0, 1.0]]
    assert np.allclose(result, expected), f"Zero matrix test failed: {result} != {expected}"

    # Test with diagonal matrix
    diag = [[2.0, 0.0], [0.0, 3.0]]
    result = compute_matrix_exponential(diag, 0)
    expected = [[np.exp(2.0), 0.0], [0.0, np.exp(3.0)]]
    assert np.allclose(result, expected), f"Diagonal test failed: {result} != {expected}"

    print("All tests passed!")

if __name__ == "__main__":
    test_matrix_exponential()

import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0
        self.gsl_matrix = None

    def allocate_gsl_matrix(self):
        gsl.gsl_matrix_alloc.restype = ctypes.POINTER(ctypes.c_double * self.cols * self.rows)
        self.gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        if not self.gsl_matrix:
            raise MemoryError("Failed to allocate GSL matrix")

    def free_gsl_matrix(self):
        if self.gsl_matrix:
            gsl.gsl_matrix_free(self.gsl_matrix)
            self.gsl_matrix = None

    def copy_to_gsl(self):
        for i in range(self.rows):
            for j in range(self.cols):
                self.gsl_matrix[0][i][j] = self.data[i][j]

    def copy_from_gsl(self):
        result = []
        for i in range(self.rows):
            row = []
            for j in range(self.cols):
                row.append(self.gsl_matrix[0][i][j])
            result.append(row)
        return result

def matrix_to_gsl(matrix):
    if not matrix or not all(len(row) == len(matrix[0]) for row in matrix):
        raise ValueError("Invalid matrix dimensions")
    gsl_matrix = GSLMatrix(matrix)
    gsl_matrix.allocate_gsl_matrix()
    gsl_matrix.copy_to_gsl()
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    return gsl_matrix.copy_from_gsl()

def compute_matrix_exponential(matrix, mode):
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise TypeError("Matrix must be a 2D list")
    if len(matrix) == 0 or len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square and non-empty")
    if not all(isinstance(x, (int, float)) for row in matrix for x in row):
        raise TypeError("Matrix elements must be numbers")
    if not isinstance(mode, int):
        raise TypeError("Mode must be an integer")

    gsl_matrix = matrix_to_gsl(matrix)
    try:
        result_matrix = GSLMatrix([[0.0] * len(matrix) for _ in range(len(matrix))])
        result_matrix.allocate_gsl_matrix()

        gsl.gsl_linalg_exponential_ss.argtypes = [
            ctypes.POINTER(ctypes.c_double * len(matrix) * len(matrix)),
            ctypes.POINTER(ctypes.c_double * len(matrix) * len(matrix)),
            ctypes.c_int
        ]
        gsl.gsl_linalg_exponential_ss(gsl_matrix.gsl_matrix, result_matrix.gsl_matrix, mode)

        result = gsl_matrix_to_numpy(result_matrix)
        return result
    finally:
        gsl_matrix.free_gsl_matrix()
        if 'result_matrix' in locals():
            result_matrix.free_gsl_matrix()

# Load GSL libraries
try:
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
except OSError as e:
    raise RuntimeError(f"Failed to load GSL libraries: {e}")

# Test cases
def test_matrix_exponential():
    # Test 1: Identity matrix
    identity = [[1.0, 0.0], [0.0, 1.0]]
    result = compute_matrix_exponential(identity, 0)
    expected = [[np.exp(1.0), 0.0], [0.0, np.exp(1.0)]]
    assert np.allclose(result, expected, atol=1e-6), f"Identity test failed: {result} != {expected}"

    # Test 2: Zero matrix
    zero = [[0.0, 0.0], [0.0, 0.0]]
    result = compute_matrix_exponential(zero, 0)
    expected = [[1.0, 0.0], [0.0, 1.0]]
    assert np.allclose(result, expected, atol=1e-6), f"Zero test failed: {result} != {expected}"

    # Test 3: Diagonal matrix
    diagonal = [[2.0, 0.0], [0.0, 3.0]]
    result = compute_matrix_exponential(diagonal, 0)
    expected = [[np.exp(2.0), 0.0], [0.0, np.exp(3.0)]]
    assert np.allclose(result, expected, atol=1e-6), f"Diagonal test failed: {result} != {expected}"

    print("All tests passed!")

if __name__ == "__main__":
    test_matrix_exponential()

