import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = np.array(data, dtype=ctypes.c_double)
        self.rows, self.cols = self.data.shape
        self.gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.gsl_matrix, i, j, self.data[i, j])

    def free(self):
        gsl.gsl_matrix_free(self.gsl_matrix)

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl_matrix.rows
    cols = gsl_matrix.cols
    result = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            result[i, j] = gsl.gsl_matrix_get(gsl_matrix.gsl_matrix, i, j)
    return result.tolist()

def compute_matrix_exponential(matrix, mode):
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise ValueError("Input must be a 2D list")
    rows = len(matrix)
    if rows == 0:
        raise ValueError("Matrix cannot be empty")
    cols = len(matrix[0])
    if not all(len(row) == cols for row in matrix):
        raise ValueError("All rows must have the same length")
    if rows != cols:
        raise ValueError("Matrix must be square")

    gsl_mat = matrix_to_gsl(matrix)
    result_gsl = gsl.gsl_matrix_alloc(rows, cols)

    try:
        gsl.gsl_linalg_exponential_ss(gsl_mat.gsl_matrix, result_gsl, mode)
        result = gsl_matrix_to_numpy(GSLMatrix.__new__(GSLMatrix))
        result.gsl_matrix = result_gsl
