import ctypes

class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0
        self.data = (ctypes.c_double * (2 * self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[2 * (i * self.cols + j)] = data[i][j].real
                self.data[2 * (i * self.cols + j) + 1] = data[i][j].imag

def list_to_gsl_matrix(matrix):
    return GSLMatrix(matrix)

def add_matrices(matrix_a, matrix_b):
    if len(matrix_a) != len(matrix_b) or len(matrix_a[0]) != len(matrix_b[0]):
        raise ValueError("Matrices must have the same dimensions")

    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl_matrix_add = gsl.gsl_matrix_complex_add
    gsl_matrix_add.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl_matrix_add.restype = ctypes.c_int

    gsl_a = list_to_gsl_matrix(matrix_a)
    gsl_b = list_to_gsl_matrix(matrix_b)

    result = GSLMatrix(matrix_a)
    gsl_matrix_add(result.data, gsl_b.data)

    output = []
    for i in range(result.rows):
        row = []
        for j in range(result.cols):
            real = result.data[2 * (i * result.cols + j)]
            imag = result.data[2 * (i * result.cols + j) + 1]
            row.append(complex(real, imag))
        output.append(row)

    return output

