import ctypes

def initialize_matrix(rows, cols):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_matrix_alloc.restype = ctypes.c_void_p
    gsl.gsl_matrix_alloc.argtypes = [ctypes.c_size_t, ctypes.c_size_t]

    gsl.gsl_matrix_free.argtypes = [ctypes.c_void_p]

    gsl.gsl_matrix_get.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_size_t]
    gsl.gsl_matrix_get.restype = ctypes.c_double

    matrix_ptr = gsl.gsl_matrix_alloc(rows, cols)
    if not matrix_ptr:
        return "Failed to allocate matrix"

    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(matrix_ptr, i, j, 0.0)

    dim_check = True
    for i in range(rows):
        for j in range(cols):
            if gsl.gsl_matrix_get(matrix_ptr, i, j) != 0.0:
                dim_check = False
                break
        if not dim_check:
            break

    gsl.gsl_matrix_free(matrix_ptr)

    if dim_check:
        return f"Matrix initialized successfully with dimensions {rows}x{cols}"
    else:
        return "Matrix initialization verification failed"

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.result = initialize_matrix(rows, cols)

