class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        self.ptr = ctypes.cast(self.data, ctypes.POINTER(ctypes.c_double))

    def free(self):
        pass

    def to_numpy(self):
        return np.ctypeslib.as_array(self.data).reshape((self.rows, self.cols))

