    covar_matrix = GSLMatrix(p, p)

    gsl.gsl_multifit_nlinear_covar.argtypes = [
        ctypes.POINTER(ctypes.c_double), ctypes.c_double, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double)
    ]
    gsl.gsl_multifit_nlinear_covar.restype = None

    gsl.gsl_multifit_nlinear_covar(jac_matrix.ptr, epsrel, n, p, covar_matrix.ptr)

    covar_np = covar_matrix.to_numpy()
