import sys

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()

    def set_element(self, i, j, value):
        if 0 <= i < self.rows and 0 <= j < self.cols:
            self.data[i * self.cols + j] = value
        else:
            raise IndexError("Index out of bounds")

    def get_element(self, i, j):
        if 0 <= i < self.rows and 0 <= j < self.cols:
            return self.data[i * self.cols + j]
        else:
            raise IndexError("Index out of bounds")

def create_and_manipulate_matrix():
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        print(f"Error loading GSL libraries: {e}", file=sys.stderr)
        return None

