import ctypes

# Load the required libraries
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define the GSLFunction class
class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x, params):
        return self.func(x)

# Define the linear function
def linear_func(x):
    return x

# Define the quadratic function
def quadratic_func(x):
    return x * x

# Define the compute_derivative function
def compute_derivative(func, x):
    gsl_func = GSLFunction(func)
    gsl_function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(gsl_func)
    derivative = ctypes.c_double()
    error = ctypes.c_double()
    gsl.gsl_diff_backward(gsl_function, ctypes.c_void_p(), ctypes.c_double(x), ctypes.byref(derivative), ctypes.byref(error))
    return (derivative.value, error.value)

