        self.rng_type = self.gsl.gsl_rng_default
        self.rng = self.gsl.gsl_rng_alloc(self.rng_type)

    def generate_random_number(self, seed):
        self.gsl.gsl_rng_set(self.rng, seed)
        return self.gsl.gsl_rng_get(self.rng)

