def bernoulli_trial(rng, p):
    if not isinstance(rng, gsl_rng):
        raise TypeError("rng must be a gsl_rng object")
    if not isinstance(p, (int, float)):
        raise TypeError("p must be a number")
    if p < 0 or p > 1:
        raise ValueError("p must be between 0 and 1")

    result = gsl.gsl_ran_bernoulli(rng.ptr, ctypes.c_double(p))
    return int(result)

class gsl_rng:
    def __init__(self, seed=None):
        # Use default GSL RNG type (gsl_rng_mt19937)
        self.ptr = gsl.gsl_rng_alloc(ctypes.c_void_p(0))
        if self.ptr is None:
            raise RuntimeError("Failed to allocate GSL RNG")

        if seed is not None:
            self.set_seed(seed)

    def set_seed(self, seed):
        if not isinstance(seed, int):
            raise TypeError("seed must be an integer")
        gsl.gsl_rng_set(self.ptr, ctypes.c_ulong(seed))

