import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = np.array(data, dtype=ctypes.c_double)
        self.rows, self.cols = self.data.shape
        self.gsl_matrix = None

    def to_gsl(self):
        if self.gsl_matrix is None:
            self.gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
            for i in range(self.rows):
                for j in range(self.cols):
                    gsl.gsl_matrix_set(self.gsl_matrix, i, j, self.data[i, j])
        return self.gsl_matrix

    def from_gsl(self, gsl_matrix):
        result = np.zeros((self.rows, self.cols))
        for i in range(self.rows):
            for j in range(self.cols):
                result[i, j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
        return result.tolist()

    def free(self):
        if self.gsl_matrix is not None:
            gsl.gsl_matrix_free(self.gsl_matrix)
            self.gsl_matrix = None

def is_positive_definite(matrix):
    try:
        np.linalg.cholesky(matrix)
        return True
    except np.linalg.LinAlgError:
        return False

def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite")

    gsl_matrix = GSLMatrix(matrix)
    gsl_mat_ptr = gsl_matrix.to_gsl()

    result = gsl.gsl_linalg_cholesky_decomp(gsl_mat_ptr)
    if result != 0:
        gsl_matrix.free()
        raise RuntimeError("Cholesky decomposition failed")

    decomp_matrix = gsl_matrix.from_gsl(gsl_mat_ptr)
    gsl_matrix.free()

    for i in range(len(decomp_matrix)):
        for j in range(i + 1, len(decomp_matrix)):
            decomp_matrix[i][j] = 0.0

    return decomp_matrix

