import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = np.array(data, dtype=np.double)
        self.n = self.data.shape[0]
        self.gsl_matrix = None
        self._allocate()

    def _allocate(self):
        self.gsl_matrix = gsl.gsl_matrix_alloc(self.n, self.n)
        if not self.gsl_matrix:
            raise MemoryError("Failed to allocate GSL matrix")
        for i in range(self.n):
            for j in range(self.n):
                gsl.gsl_matrix_set(self.gsl_matrix, i, j, self.data[i, j])

    def to_list(self):
        result = []
        for i in range(self.n):
            row = []
            for j in range(self.n):
                row.append(gsl.gsl_matrix_get(self.gsl_matrix, i, j))
            result.append(row)
        return result

    def __del__(self):
        if self.gsl_matrix:
            gsl.gsl_matrix_free(self.gsl_matrix)

def is_positive_definite(matrix):
    try:
        np_matrix = np.array(matrix, dtype=np.double)
        return np.all(np.linalg.eigvals(np_matrix) > 0)
    except:
        return False

def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite")

    gsl_matrix = GSLMatrix(matrix)

    result = gsl.gsl_linalg_cholesky_decomp(gsl_matrix.gsl_matrix)
    if result != 0:
        raise RuntimeError(f"Cholesky decomposition failed with error code {result}")

    return gsl_matrix.to_list()

