import ctypes

class GSLBlock:
    def __init__(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def allocate_and_free_block(self, n):
        try:
            block_ptr = self.gsl.gsl_block_alloc(n)
            if not block_ptr:
                return False

            calloc_block_ptr = self.gsl.gsl_block_calloc(n)
            if not calloc_block_ptr:
                self.gsl.gsl_block_free(block_ptr)
                return False

            self.gsl.gsl_block_free(block_ptr)
            self.gsl.gsl_block_free(calloc_block_ptr)
            return True
        except:
            return False

