import ctypes
import sys

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except OSError as e:
        print(f"Error loading GSL libraries: {e}", file=sys.stderr)
        sys.exit(1)

def setup_gsl_functions(gsl_lib):
    gsl_lib.gsl_cdf_negative_binomial_P.argtypes = [ctypes.c_uint, ctypes.c_double, ctypes.c_double]
    gsl_lib.gsl_cdf_negative_binomial_P.restype = ctypes.c_double
    gsl_lib.gsl_cdf_negative_binomial_Q.argtypes = [ctypes.c_uint, ctypes.c_double, ctypes.c_double]
    gsl_lib.gsl_cdf_negative_binomial_Q.restype = ctypes.c_double

def negative_binomial_cdf_P(k, p, n):
    if not isinstance(k, int) or k < 0:
        raise ValueError("k must be a non-negative integer")
    if not (0.0 <= p <= 1.0):
        raise ValueError("p must be between 0.0 and 1.0")
    if n <= 0.0:
        raise ValueError("n must be positive")
    gsl = load_gsl_libraries()
    setup_gsl_functions(gsl)
    return gsl.gsl_cdf_negative_binomial_P(k, p, n)

def negative_binomial_cdf_Q(k, p, n):
    if not isinstance(k, int) or k < 0:
        raise ValueError("k must be a non-negative integer")
    if not (0.0 <= p <= 1.0):
        raise ValueError("p must be between 0.0 and 1.0")
    if n <= 0.0:
        raise ValueError("n must be positive")
    gsl = load_gsl_libraries()
    setup_gsl_functions(gsl)
    return gsl.gsl_cdf_negative_binomial_Q(k, p, n)

def test_negative_binomial_cdf():
    test_cases = [
        (0, 0.5, 1.0),
        (5, 0.3, 2.0),
        (10, 0.7, 5.0),
        (1, 0.1, 0.5),
        (100, 0.9, 10.0)
    ]

    for k, p, n in test_cases:
        try:
            result_P = negative_binomial_cdf_P(k, p, n)
            result_Q = negative_binomial_cdf_Q(k, p, n)
            print(f"k={k}, p={p}, n={n}: P={result_P:.6f}, Q={result_Q:.6f}, Sum={result_P + result_Q:.6f}")
        except Exception as e:
            print(f"Error with k={k}, p={p}, n={n}: {e}")

    invalid_cases = [
        (-1, 0.5, 1.0),
        (5, -0.1, 2.0),
        (10, 1.1, 5.0),
        (1, 0.5, 0.0),
        (5, 0.5, -1.0)
    ]

    for k, p, n in invalid_cases:
        try:
            negative_binomial_cdf_P(k, p, n)
            print(f"Unexpected success with invalid input: k={k}, p={p}, n={n}")
        except ValueError as e:
            print(f"Correctly caught error for k={k}, p={p}, n={n}: {e}")

if __name__ == "__main__":
    test_negative_binomial_cdf()

