import ctypes
import sys

class GslFftComplexWavetable:
    pass

def allocate_wavetable(n):
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    gsl.gsl_fft_complex_wavetable_alloc.argtypes = [ctypes.c_size_t]
    gsl.gsl_fft_complex_wavetable_alloc.restype = ctypes.POINTER(GslFftComplexWavetable)

    if n <= 0:
        raise ValueError("FFT size n must be a positive integer")

    wavetable_ptr = gsl.gsl_fft_complex_wavetable_alloc(n)

    if not wavetable_ptr:
        raise RuntimeError("Failed to allocate wavetable")

    return wavetable_ptr

if __name__ == "__main__":
    try:
        n = 1024
        wavetable_ptr = allocate_wavetable(n)
        assert wavetable_ptr is not None, "Wavetable pointer should not be None"
        assert isinstance(wavetable_ptr, ctypes.POINTER(GslFftComplexWavetable)), "Return type should be a pointer to GslFftComplexWavetable"

        try:
            allocate_wavetable(0)
            assert False, "Should have raised ValueError for n=0"
        except ValueError:
            pass

