import ctypes
import sys

def scale_complex_vector(N, alpha, X, incX):
    if not isinstance(N, int) or N < 0:
        raise ValueError("N must be a non-negative integer")
    if not isinstance(alpha, (float, int)):
        raise ValueError("alpha must be a float or integer")
    if not isinstance(X, list):
        raise ValueError("X must be a list")
    if not isinstance(incX, int) or incX <= 0:
        raise ValueError("incX must be a positive integer")
    if len(X) < N * incX:
        raise ValueError("X list is too short for the given N and incX")

    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    cblas.cblas_csscal.argtypes = [ctypes.c_int, ctypes.c_float, ctypes.c_void_p, ctypes.c_int]

    x_array = (ctypes.c_float * (2 * len(X)))()
    for i in range(len(X)):
        x_array[2*i] = ctypes.c_float(X[i].real)
        x_array[2*i+1] = ctypes.c_float(X[i].imag)

