import ctypes
import sys

def scale_complex_vector(N, alpha, X, incX):
    if not isinstance(N, int) or N < 0:
        raise ValueError("N must be a non-negative integer")
    if not isinstance(alpha, (float, int)):
        raise ValueError("alpha must be a float or integer")
    if not isinstance(X, list):
        raise ValueError("X must be a list")
    if not isinstance(incX, int) or incX <= 0:
        raise ValueError("incX must be a positive integer")
    if len(X) < N * incX:
        raise ValueError("X list is too short for given N and incX")

    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    cblas.cblas_csscal.argtypes = [ctypes.c_int, ctypes.c_float, ctypes.POINTER(ctypes.c_float), ctypes.c_int]

    x_array = (ctypes.c_float * (2 * len(X)))()
    for i, comp in enumerate(X):
        x_array[2*i] = ctypes.c_float(comp.real)
        x_array[2*i+1] = ctypes.c_float(comp.imag)

    cblas.cblas_csscal(N, ctypes.c_float(alpha), x_array, incX)

    for i in range(len(X)):
        X[i] = complex(x_array[2*i], x_array[2*i+1])

if __name__ == "__main__":
    try:
        X1 = [complex(1.0, 2.0), complex(3.0, 4.0)]
        scale_complex_vector(2, 2.0, X1, 1)
        assert X1[0] == complex(2.0, 4.0) and X1[1] == complex(6.0, 8.0), "Test 1 failed"

        X2 = [complex(1.0, 0.0), complex(0.0, 1.0), complex(-1.0, -1.0)]
        scale_complex_vector(3, 0.5, X2, 1)
        assert X2[0] == complex(0.5, 0.0) and X2[1] == complex(0.0, 0.5) and X2[2] == complex(-0.5, -0.5), "Test 2 failed"

        X3 = [complex(1.0, 1.0)] * 5
        scale_complex_vector(2, 3.0, X3, 2)
        assert X3[0] == complex(3.0, 3.0) and X3[1] == complex(1.0, 1.0) and X3[2] == complex(3.0, 3.0) and X3[3] == complex(1.0, 1.0) and X3[4] == complex(1.0, 1.0), "Test 3 failed"

        print("All tests passed!")
    except Exception as e:
        print(f"Test error: {e}")
        sys.exit(1)
